<?php
/** Proof — drafting and the lines (spec "Proof", 1): a draft for Acme with Add unbilled — the counts, the no-rate hours named, the total; a second add adds nothing; one item removed → the line recomputed and the item WIP again; a fixed line, a discount and a tax rate per line; the currency and PO from the engagement; a draft deleted burns no number and releases its items. */
require __DIR__ . '/lib.php';
$w = billing_world(); $acme = $w['acme']; $beta = $w['beta'];
$marco = as_member(27); $bea = as_member(28); $priya = as_member(26); $dana = as_member(30);
$acmeNum = (string) one('SELECT number FROM engagements WHERE id = :e', ['e' => $acme]);
$seq0 = (int) one("SELECT next_value FROM document_sequences WHERE kind = 'invoice'");

echo "1. Draft with Add unbilled\n";
ok(wip($acme) === '2359.00', 'the world: 2,359.00 approved and unbilled on Acme (time 1,260.00 + 875.00, expenses 140.00, usage 84.00)');
$since = last_activity_id();
[$c, $b] = draft($marco, $acme, ['period_start' => '2026-09-01', 'period_end' => '2026-09-30', 'memo' => 'SMOKE September']);
$d0 = (int) ($b['record_id'] ?? 0);
$cnt = $b['counts'] ?? [];
ok($c === 200 && $d0 > 0 && $b['status'] === 'draft' && $b['currency'] === 'USD' && $b['total'] === '2359.00', "invoice_draft by the manager: draft #$d0, USD, total 2,359.00");
ok(($cnt['time_lines'] ?? 0) === 2 && $cnt['time_entries_billed'] === 4 && $cnt['expense_lines'] === 2 && $cnt['usage_lines'] === 3 && $cnt['milestone_lines'] === 0, 'the counts: two time lines by person, four entries, two expenses, three usage charges, no milestone');
ok($cnt['time_no_rate'] === 1 && $cnt['no_rate_hours'] === '4.00' && str_contains((string) $b['warning'], '4 h on ' . $acmeNum . ' have no rate'), 'the no-rate hours are named: "' . ($b['warning'] ?? '') . '"');
$i = inv($d0);
ok($i['status'] === 'draft' && $i['number'] === null && $i['subtotal'] === '2359.00' && $i['tax_total'] === '0.00' && $i['total'] === '2359.00' && $i['balance_due'] === '2359.00' && (int) $i['client_id'] === $w['client'] && $i['period_start'] === '2026-09-01', 'the database holds a draft with no number and the totals it computed');
$ls = lines_of($d0);
ok(count($ls) === 7 && array_count_values(array_column($ls, 'kind')) === ['time' => 2, 'expense' => 2, 'usage' => 3] && items_of($d0) === 9, 'seven lines (2 time, 2 expense, 3 usage) with nine backing items');
$byDesc = array_column($ls, null, 'description');
$pl = array_values(array_filter($ls, static fn ($l) => $l['kind'] === 'time' && str_contains($l['description'], 'Priya')))[0] ?? [];
ok($pl && $pl['quantity'] === '7.0000' && $pl['unit_price'] === '180.00' && $pl['line_total'] === '1260.00' && $pl['unit'] === 'hours', 'Priya\'s line: 7 hours at 180.00 = 1,260.00 (the rate snapshotted at approval)');
$log = activity('invoice.draft', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && (int) $log[0]['invoice_id'] === $d0 && (int) $log[0]['engagement_id'] === $acme && (int) $log[0]['client_id'] === $w['client'] && $after['amount'] === '2359.00' && $after['currency'] === 'USD' && $after['counts']['usage_lines'] === 3 && $log[0]['source'] === 'web', 'invoice.draft logged with invoice_id, engagement_id, client_id, amount and currency, and the counts');
ok(wip($acme) === '0', 'every approved item is now billed: nothing unbilled (billed is one truth)');

echo "2. A second add adds nothing\n";
$since = last_activity_id();
[$c, $b] = act($marco, '/invoices/add-unbilled.php', ['invoice' => $d0]);
ok($c === 200 && $b['counts']['time_lines'] === 0 && $b['counts']['expense_lines'] === 0 && $b['counts']['usage_lines'] === 0 && count(lines_of($d0)) === 7 && inv($d0)['total'] === '2359.00', 'invoice_add_unbilled again: zero new lines, the total unchanged');
ok($b['counts']['time_no_rate'] === 1 && count(activity('invoice.add_unbilled', $since)) === 1, 'the no-rate hours are still named, and the call is logged (invoice.add_unbilled)');

echo "3. Remove one item; the line is recomputed; the item is WIP again\n";
$priyaItems = q("SELECT x.id AS item_id, t.id AS entry_id, t.hours FROM invoice_line_items x JOIN time_entries t ON t.id = x.time_entry_id WHERE x.invoice_id = :i AND t.member_id = 26 ORDER BY t.entry_date", ['i' => $d0]);
$since = last_activity_id();
[$c, $b] = act($marco, '/invoices/items/remove.php', ['item' => (int) $priyaItems[1]['item_id']]);
$pl = q('SELECT * FROM invoice_lines WHERE id = :l', ['l' => $pl['id']])[0];
ok($c === 200 && $b['line_removed'] === false && $b['items_left'] === 1 && $pl['quantity'] === '4.0000' && $pl['line_total'] === '720.00' && inv($d0)['total'] === '1819.00', 'invoice_item_remove: Priya\'s line is now 4 hours = 720.00 and the invoice 1,819.00');
ok(!(bool) one("SELECT ct_item_billed('time_entry', :e)", ['e' => (int) $priyaItems[1]['entry_id']]) && wip($acme) === '540.00', 'the removed entry is unbilled again (540.00 of WIP)');
$log = activity('invoice.item_remove', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true)['kind'] === 'time' && json_decode((string) $log[0]['after'], true)['amount'] === '540.00' && json_decode((string) $log[0]['after'], true)['currency'] === 'USD', 'invoice.item_remove logged (kind, amount, currency)');
[$c, $b] = act($marco, '/invoices/add-unbilled.php', ['invoice' => $d0]);
ok($c === 200 && $b['counts']['time_lines'] === 1 && $b['counts']['time_entries_billed'] === 1 && inv($d0)['total'] === '2359.00' && wip($acme) === '0', 'pulling again takes it back (a line of its own): 2,359.00 and nothing unbilled');
$expLine = q("SELECT l.id, x.expense_id FROM invoice_lines l JOIN invoice_line_items x ON x.line_id = l.id WHERE l.invoice_id = :i AND l.kind = 'expense' ORDER BY l.id LIMIT 1", ['i' => $d0])[0];
[$c, $b] = act($marco, '/invoices/lines/remove.php', ['line' => (int) $expLine['id']]);
ok($c === 200 && $b['items_released'] === 1 && !(bool) one("SELECT ct_item_billed('expense', :e)", ['e' => (int) $expLine['expense_id']]), 'invoice_line_remove: an expense line goes and its expense is unbilled again');
act($marco, '/invoices/add-unbilled.php', ['invoice' => $d0]);

echo "4. A fixed line, a discount, a tax rate per line\n";
$vat = (int) one("INSERT INTO tax_rates (name, rate) VALUES ('SMOKE VAT', 10) RETURNING id");
$since = last_activity_id();
[$c, $b] = act($marco, '/invoices/lines/save.php', ['invoice' => $d0, 'kind' => 'fixed', 'description' => 'SMOKE Workshop', 'unit_price' => '500.00', 'tax_rate' => $vat]);
$fx = (int) $b['line_id'];
$l = q('SELECT * FROM invoice_lines WHERE id = :l', ['l' => $fx])[0];
ok($c === 200 && $l['kind'] === 'fixed' && $l['line_subtotal'] === '500.00' && $l['line_tax'] === '50.00' && $l['line_total'] === '550.00' && $l['tax_rate'] === '10.0000', 'invoice_line_save: a fixed line of 500.00 with VAT 10 % carries 50.00 tax (the database\'s arithmetic)');
[$c, $b] = act($marco, '/invoices/lines/save.php', ['invoice' => $d0, 'kind' => 'discount', 'description' => 'SMOKE Goodwill', 'unit_price' => '100']);
$ds = q('SELECT * FROM invoice_lines WHERE id = :l', ['l' => (int) $b['line_id']])[0];
$i = inv($d0);
ok($c === 200 && $ds['unit_price'] === '-100.00' && $ds['line_total'] === '-100.00' && $i['subtotal'] === '2759.00' && $i['tax_total'] === '50.00' && $i['total'] === '2809.00', 'a discount of 100 is stored negative; the totals strip: subtotal 2,759.00, tax 50.00, total 2,809.00');
$log = activity('invoice.line_save', $since);
ok(count($log) === 2 && json_decode((string) $log[0]['after'], true)['amount'] === '550.00' && json_decode((string) $log[0]['after'], true)['currency'] === 'USD' && (int) $log[0]['invoice_id'] === $d0, 'invoice.line_save logged with the line\'s amount and the currency');
[$c, $b] = act($marco, '/invoices/lines/save.php', ['invoice' => $d0, 'line' => $fx, 'description' => 'SMOKE Workshop (two days)', 'unit_price' => '600.00']);
ok($c === 200 && q('SELECT line_total FROM invoice_lines WHERE id = :l', ['l' => $fx])[0]['line_total'] === '660.00', 'a hand line changes: 600.00 + 10 % = 660.00');
[$c, $b] = act($marco, '/invoices/lines/save.php', ['invoice' => $d0, 'line' => (int) $pl['id'], 'description' => 'SMOKE Priya hours', 'tax_rate' => $vat]);
$pl2 = q('SELECT * FROM invoice_lines WHERE id = :l', ['l' => (int) $pl['id']])[0];
ok($c === 200 && $pl2['description'] === 'SMOKE Priya hours' && $pl2['quantity'] === '4.0000' && $pl2['line_tax'] === '72.00', 'a backed line changes its description and tax (720.00 at 10 % = 72.00), its quantity untouched');
[$c, $b] = act($marco, '/invoices/lines/save.php', ['invoice' => $d0, 'line' => (int) $pl['id'], 'quantity' => '9']);
ok($c === 422 && str_contains(msg($b), 'bills 1 item'), 'a line that bills items refuses a new quantity, in words (' . msg($b) . ')');
[$c, $b] = act($marco, '/invoices/lines/save.php', ['invoice' => $d0, 'kind' => 'fixed', 'description' => '', 'unit_price' => '-5']);
ok($c === 422 && isset(fields($b)['description']) && isset(fields($b)['unit_price']), 'a blank description and a negative fixed price: 422 naming both fields');
act($marco, '/invoices/lines/remove.php', ['line' => $fx]);
act($marco, '/invoices/lines/remove.php', ['line' => (int) $ds['id']]);
act($marco, '/invoices/lines/save.php', ['invoice' => $d0, 'line' => (int) $pl['id'], 'description' => $pl['description'], 'tax_rate' => '']);

echo "5. The head: currency and PO from the engagement\n";
q("UPDATE engagements SET po_number = 'PO-77' WHERE id = :e", ['e' => $beta]);
$since = last_activity_id();
[$c, $b] = draft($bea, $beta, ['add_unbilled' => 'no']);
$d2 = (int) $b['record_id'];
$i = inv($d2);
ok($c === 200 && $i['po_number'] === 'PO-77' && $i['currency'] === 'USD' && trim((string) $i['currency']) === 'USD' && $i['status'] === 'draft' && $i['number'] === null, 'a draft for Beta carries the engagement\'s PO (PO-77) and its currency; no number');
ok((int) $i['due_date'] !== 0 && $i['due_date'] === (string) one("SELECT CAST(current_date + COALESCE((SELECT terms_days FROM clients WHERE id = :c), (SELECT default_terms_days FROM ct_settings WHERE id = 1)) AS text)", ['c' => (int) $i['client_id']]), 'the due date is the client\'s terms from the issue date (' . $i['due_date'] . ')');
$told = q("SELECT member_id, kind, record_type, record_id FROM notifications WHERE kind = 'invoice_drafted' ORDER BY id DESC LIMIT 1");
ok($told === [['member_id' => 27, 'kind' => 'invoice_drafted', 'record_type' => 'invoice', 'record_id' => $d2]], 'Billing drafted for an engagement Marco manages: he is told (invoice_drafted, in-app)');
[$c, $b] = draft($marco, $beta, ['add_unbilled' => 'no', 'po_number' => 'PO-OTHER']);
$d3 = (int) $b['record_id'];
ok($c === 200 && inv($d3)['po_number'] === 'PO-OTHER', 'a typed PO overrides the engagement\'s');
ok((int) one('SELECT count(*) FROM notifications WHERE kind = \'invoice_drafted\' AND record_id = :r', ['r' => $d3]) === 0, 'the manager drafting his own: no notice');
[$c, $b] = act($marco, '/invoices/save.php', ['invoice' => $d3, 'memo' => 'SMOKE memo']);
$i = inv($d3);
ok($c === 200 && $i['memo'] === 'SMOKE memo' && $i['po_number'] === 'PO-OTHER', 'invoice_update: a field left out stays as it was');
$log = activity('invoice.update', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true)['memo'] === 'SMOKE memo' && (int) $log[0]['engagement_id'] === $beta, 'invoice.update logged with what changed');
[$c, $b] = act($marco, '/invoices/save.php', ['invoice' => $d3, 'issue_date' => '2026-10-10', 'due_date' => '2026-10-01']);
ok($c === 422 && isset(fields($b)['due_date']), 'a due date before the issue date: 422 on the field');
[$c, $b] = act($marco, '/invoices/save.php', ['add_unbilled' => 'yes']);
ok($c === 422 && isset(fields($b)['engagement']), 'no engagement: 422 naming it');

echo "6. A draft deleted burns no number and releases its items\n";
$seq1 = (int) one("SELECT next_value FROM document_sequences WHERE kind = 'invoice'");
ok($seq1 === $seq0 && inv($d0)['number'] === null, 'so far no number was taken: drafts have none');
$since = last_activity_id();
[$c, $b] = act($marco, '/invoices/delete.php', ['invoice' => $d0]);
ok($c === 200 && inv($d0) === [] && items_of($d0) === 0 && wip($acme) === '2359.00', 'invoice_delete: the draft, its lines and items are gone; the 2,359.00 is unbilled again');
$log = activity('invoice.delete', $since);
ok(count($log) === 1 && (int) $log[0]['invoice_id'] === $d0 && json_decode((string) $log[0]['before'], true)['currency'] === 'USD' && (int) one("SELECT next_value FROM document_sequences WHERE kind = 'invoice'") === $seq0, 'invoice.delete logged; the sequence did not move (INV-00001 is still to come)');
[$c, $b] = act($marco, '/invoices/delete.php', ['invoice' => 99999]);
ok($c === 404, 'deleting what is not there: 404');
act($bea, '/invoices/delete.php', ['invoice' => $d2]); act($marco, '/invoices/delete.php', ['invoice' => $d3]);

echo "7. Gates and screens\n";
[$c, $b] = act($priya, '/invoices/save.php', ['engagement' => $acme]);
ok($c === 403 && msg($b) === 'You may not draft invoices.', 'Priya (a Consultant): 403 "You may not draft invoices."');
[$c, $b] = act($dana, '/invoices/add-unbilled.php', ['invoice' => 1]);
ok($c === 403, 'Dana: add-unbilled 403');
[$c, $d] = screen($marco, '/invoices/new?engagement=' . $acme . '&to=2026-09-30');
ok($c === 200 && $d['prefill']['engagement'] === $acme && $d['prefill']['to'] === '2026-09-30' && count($d['engagements']) >= 2, 'the add form answers with the engagements he may draft for and the prefill');
// a fresh draft to look at as HTML
[$c, $b] = draft($marco, $acme, ['period_end' => '2026-09-30']);
$d4 = (int) $b['record_id'];
$r = page($marco, '/invoices/' . $d4 . '/edit');
ok($r['code'] === 200 && str_contains($r['body'], 'id="totals-strip"') && str_contains($r['body'], 'id="invoice-lines-table"') && str_contains($r['body'], 'id="invoice-edit-add-unbilled-btn"') && str_contains($r['body'], 'id="invoice-line-save-btn"'), 'the lines editor renders: the totals strip, the table, Pull and Add a line');
$r = page($marco, '/invoices/new');
ok($r['code'] === 200 && str_contains($r['body'], 'id="invoice-form-field-engagement"') && str_contains($r['body'], 'id="invoice-form-field-add" checked'), 'the draft form renders with Add the unbilled items checked');
$r = page($marco, '/invoices/');
ok($r['code'] === 200 && str_contains($r['body'], 'id="invoice-row-' . $d4 . '"') && str_contains($r['body'], 'id="invoice-card-' . $d4 . '"') && str_contains($r['body'], 'id="invoice-list-totals"'), 'the list renders the draft as a row and as a card, with the totals footer');
[$c, $d] = screen($marco, '/invoices/' . $d4 . '/edit');
ok($c === 200 && $d['invoice']['status'] === 'draft' && count($d['invoice']['lines']) === 7 && $d['invoice']['total'] === '2359.00' && !isset($d['invoice']['lines'][0]['cost']), 'the editor as JSON: the draft with its seven lines');
finish();
